ame'])?>"></div><div class="col-md-5"><label class="form-label">Tên đăng nhập</label><input class="form-control" value="<?=e($profileUser['username']??'')?>" readonly></div><div class="col-md-4"><label class="form-label">Ngày sinh</label><input type="date" class="form-control" name="dob" value="<?=e($profile['dob'])?>"></div><div class="col-md-4"><label class="form-label">Giới tính</label><select class="form-select" name="gender"><option value="">Chưa khai báo</option><?php foreach(['Nam','Nữ','Khác'] as $gender):?><option <?=$profile['gender']===$gender?'selected':''?>><?=e($gender)?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Số điện thoại</label><input class="form-control" name="phone" value="<?=e($profile['phone'])?>"></div><div class="col-12"><label class="form-label">Email</label><input type="email" class="form-control" name="email" value="<?=e($profile['email'])?>"></div><div class="col-md-6"><label class="form-label">Quê quán</label><input class="form-control" name="hometown" value="<?=e($profile['hometown'])?>"></div><div class="col-md-6"><label class="form-label">Địa chỉ hiện tại</label><input class="form-control" name="address" value="<?=e($profile['address'])?>"></div><div class="col-12"><button class="btn btn-primary px-4"><i class="bi bi-cloud-check"></i> Lưu vào CSDL</button></div></form></div></section></div><div class="col-lg-5"><section class="card shadow-sm"><div class="card-body p-4"><h5 class="mb-3"><i class="bi bi-shield-lock text-success"></i> Đổi mật khẩu</h5><div class="security-note p-3 small mb-3">Mật khẩu mới có tối thiểu 8 ký tự. Không chia sẻ mật khẩu với người khác.</div><form method="post" class="vstack gap-3"><input type="hidden" name="csrf" value="<?=e(cds_account_csrf_token())?>"><input type="hidden" name="profile_action" value="change_password"><div><label class="form-label">Mật khẩu hiện tại</label><input type="password" class="form-control" name="current_password" required autocomplete="current-password"></div><div><label class="form-label">Mật khẩu mới</label><input type="password" class="form-control" name="new_password" required minlength="8" autocomplete="new-password"></div><div><label class="form-label">Nhập lại mật khẩu mới</label><input type="password" class="form-control" name="confirm_password" required minlength="8" autocomplete="new-password"></div><button class="btn btn-success"><i class="bi bi-key"></i> Đổi mật khẩu</button></form></div></section></div></div></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
